    public void testCreateNumberInteger() {
        Assert.assertEquals((long) 1, NumberUtils.createNumber("1"), 0);
    }

    @Test
    public void testCreateNumberBigInteger() {
        Assert.assertEquals(new BigInteger("123"), NumberUtils.createNumber("123"), 0);
    }

    @Test
    public void testCreateNumberBigDecimal() {
        Assert.assertEquals(new BigDecimal("123.456"), NumberUtils.createNumber("123.456"), 0.0001);
    }

    @Test
    public void testCreateNumberExponential() {
        Assert.assertEquals(123, NumberUtils.createNumber("123e2"), 0);
    }

    @Test
    public void testCreateNumberNegativeExponential() {
        Assert.assertEquals(-123, NumberUtils.createNumber("-123e2"), 0);
    }

    @Test
    public void testCreateNumberPrefixes() {
        assertNull(NumberUtils.createNumber("--123"));
        assertNull(NumberUtils.createNumber("-0x123"));
        assertNull(NumberUtils.createNumber("0x123"));
        assertNull(NumberUtils.createNumber("-0X123"));
    }

    @Test
    public void testCreateNumberInvalidFormat() {
        try {
            NumberUtils.createNumber("123.45");
            Assert.fail("Expected NumberFormatException");
        } catch (NumberFormatException e) {
            assertEquals("123.45 is not a valid number.", e.getMessage());
        }
    }

