            NumberUtils.createNumber("123a45");
            Assert.fail("Expected NumberFormatException");
        } catch (NumberFormatException e) {
            assertEquals("123a45 is not a valid number.", e.getMessage());
        }
    }

    @Test
    public void testCreateNumberParseError() {
        try {
            NumberUtils.createNumber("123e");
            Assert.fail("Expected NumberFormatException");
        } catch (NumberFormatException e) {
            assertEquals("123e is not a valid number.", e.getMessage());
        }
    }

    @Test
    public void testCreateNumberWhitespace() {
        try {
            NumberUtils.createNumber("  123  ");
            Assert.fail("Expected NumberFormatException");
        } catch (NumberFormatException e) {
            assertEquals("A blank string is not a valid number", e.getMessage());
        }
    }

     @Test
    public void testCreateNumberZero() {
        Assert.assertEquals((long)0, NumberUtils.createNumber("0"), 0);
    }
